"""Tests for length scoring and character variety scoring."""

import pytest
from pwcheck.scorer import _length_score, _variety_score


class TestLengthScore:
    """Tests for the _length_score function."""

    def test_short_password_below_8(self):
        assert _length_score("abc") == 0

    def test_exactly_7_chars(self):
        assert _length_score("abcdefg") == 0

    def test_exactly_8_chars(self):
        assert _length_score("abcdefgh") == 15

    def test_9_to_11_chars(self):
        assert _length_score("abcdefghi") == 15
        assert _length_score("abcdefghij") == 15
        assert _length_score("abcdefghijk") == 15

    def test_exactly_12_chars(self):
        assert _length_score("abcdefghijkl") == 30

    def test_13_to_15_chars(self):
        assert _length_score("abcdefghijklm") == 30
        assert _length_score("abcdefghijklmn") == 30
        assert _length_score("abcdefghijklmno") == 30

    def test_exactly_16_chars(self):
        assert _length_score("abcdefghijklmnop") == 40

    def test_long_password_above_16(self):
        assert _length_score("a" * 20) == 40

    def test_empty_string(self):
        assert _length_score("") == 0


class TestVarietyScore:
    """Tests for the _variety_score function."""

    def test_only_lowercase(self):
        assert _variety_score("abcdefg") == 7

    def test_only_uppercase(self):
        assert _variety_score("ABCDEFG") == 7

    def test_only_digits(self):
        assert _variety_score("1234567") == 8

    def test_only_special(self):
        assert _variety_score("!@#$%^&*") == 8

    def test_lowercase_and_uppercase(self):
        assert _variety_score("Abcdefg") == 14

    def test_lowercase_and_digits(self):
        assert _variety_score("abc123") == 15

    def test_lowercase_and_special(self):
        assert _variety_score("abc!@#") == 15

    def test_uppercase_and_digits(self):
        assert _variety_score("ABC123") == 15

    def test_three_categories_lower_upper_digit(self):
        assert _variety_score("Abc123") == 22

    def test_three_categories_lower_upper_special(self):
        assert _variety_score("Abc!@#") == 22

    def test_all_four_categories(self):
        assert _variety_score("Abc123!") == 30

    def test_empty_string(self):
        assert _variety_score("") == 0

    def test_mixed_with_repeated_chars(self):
        # Variety depends on categories present, not uniqueness of chars
        assert _variety_score("Aa1!") == 30

"""Command-line interface for pwcheck."""

import argparse
import json
import sys
from typing import List, Optional


def build_parser() -> argparse.ArgumentParser:
    """Build and return the argument parser."""
    parser = argparse.ArgumentParser(
        prog="pwcheck",
        description="Check password strength.",
    )
    parser.add_argument(
        "password",
        nargs="?",
        help="Password to check (omit when using --file).",
    )
    parser.add_argument(
        "--file",
        type=argparse.FileType("r"),
        dest="input_file",
        help="Read passwords from a file (one per line).",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        default=False,
        help="Output results as JSON.",
    )
    return parser


def _result_to_dict(result) -> dict:
    """Convert a ScoringResult (or any result object) to a plain dict."""
    if hasattr(result, "__dataclass_fields__"):
        from dataclasses import asdict
        return asdict(result)
    # Already a dict or simple mapping
    return dict(result)


def check_password(password: str) -> dict:
    """Return a strength assessment for *password*.

    Delegates to pwcheck.scorer when available; falls back to a minimal
    built-in heuristic so the CLI works even before scorer is implemented.
    """
    try:
        from pwcheck import scorer

        result = scorer.score_password(password)
        return _result_to_dict(result)
    except ImportError:
        # Minimal fallback heuristic
        length = len(password)
        has_lower = bool(set(password) & set("abcdefghijklmnopqrstuvwxyz"))
        has_upper = bool(set(password) & set("ABCDEFGHIJKLMNOPQRSTUVWXYZ"))
        has_digit = bool(set(password) & set("0123456789"))
        has_special = bool(set(password) & set("!@#$%^&*()-_=+[]{}|;:',.<>?/\\~`"))

        variety = sum([has_lower, has_upper, has_digit, has_special])
        score = min(length * 4 + variety * 10, 100)

        if score < 30:
            rating = "weak"
        elif score < 60:
            rating = "moderate"
        else:
            rating = "strong"

        return {
            "password": password,
            "length": length,
            "variety": variety,
            "score": score,
            "rating": rating,
        }


def format_text(result: dict) -> str:
    """Format a single result as human-readable text."""
    lines = [
        f"Password: {result.get('password', '***')}",
        f"Length:   {result.get('length_score', '?')}",
        f"Variety:  {result.get('variety_score', '?')} points",
        f"Score:    {result.get('score', '?')}/100",
        f"Rating:   {result.get('rating', 'unknown')}",
    ]
    if result.get("suggestions"):
        lines.append("Suggestions:")
        for s in result["suggestions"]:
            lines.append(f"  - {s}")
    return "\n".join(lines)


def main(argv: Optional[List[str]] = None) -> int:
    """Entry point for the CLI."""
    parser = build_parser()
    args = parser.parse_args(argv)

    if not args.password and not args.input_file:
        parser.error("Provide a password or use --file.")

    results: List[dict] = []

    # --- passwords from file ------------------------------------------------
    if args.input_file:
        with args.input_file as fh:
            for line in fh:
                pw = line.rstrip("\n")
                if pw:
                    result = check_password(pw)
                    result["password"] = pw
                    results.append(result)

    # --- password from argument ----------------------------------------------
    elif args.password is not None:
        result = check_password(args.password)
        result["password"] = args.password
        results.append(result)

    # --- output ---------------------------------------------------------------
    if args.json:
        print(json.dumps(results, indent=2))
    else:
        for i, result in enumerate(results):
            if i > 0:
                print()
            print(format_text(result))

    return 0


if __name__ == "__main__":
    sys.exit(main())
